import test from 'node:test';import assert from 'node:assert/strict';import {layoutFieldLabels} from '../label-layout.js';
const area=(a,b)=>Math.max(0,Math.min(a.x+a.w,b.x+b.w)-Math.max(a.x,b.x))*Math.max(0,Math.min(a.y+a.h,b.y+b.h)-Math.max(a.y,b.y));
test('nearby field names move away from faces and other labels without escaping the visible world',()=>{const bounds={x:0,y:0,w:320,h:230},faces=[{x:80,y:90,w:45,h:70},{x:135,y:80,w:45,h:70}],rows=layoutFieldLabels([{text:'Hesper',x:100,y:110,w:100},{text:'Crew',x:150,y:110,w:100}],{bounds,faces});for(const r of rows){assert.ok(r.x>=0&&r.y>=0&&r.x+r.w<=320&&r.y+r.h<=230);assert.equal(faces.reduce((n,f)=>n+area(r,f),0),0);}assert.equal(area(...rows),0);});
test('a narrow viewport bounds long labels and preserves the subject anchor',()=>{const [r]=layoutFieldLabels([{text:'A long clue',x:-20,y:-20,w:210}],{bounds:{x:0,y:0,w:140,h:90}});assert.equal(r.w,140);assert.equal(r.x,0);assert.equal(r.anchorX,-20);assert.ok(r.y>=0);});
